use std::collections::HashMap;

struct Solution;

impl Solution {
    pub fn num_triplets(nums1: Vec<i32>, nums2: Vec<i32>) -> i32 {
        fn count_triplets(arr1: &[i32], arr2: &[i32]) -> i32 {
            let mut product_count = HashMap::new();
            let n = arr2.len();
            for i in 0..n {
                for j in i+1..n {
                    let prod = arr2[i] as i64 * arr2[j] as i64;
                    *product_count.entry(prod).or_insert(0) += 1;
                }
            }
            let mut res = 0;
            for &x in arr1 {
                let sq = (x as i64) * (x as i64);
                if let Some(&count) = product_count.get(&sq) {
                    res += count;
                }
            }
            res
        }
        count_triplets(&nums1, &nums2) + count_triplets(&nums2, &nums1)
    }
}

